function validate([nums, removeQueries]) {
  if (!Array.isArray(nums) || !Array.isArray(removeQueries)) return 'Both inputs must be arrays.';
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 100000 values.';
  if (removeQueries.length !== n) return 'removeQueries must have the same length as nums.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value of nums is between 1 and 10^9.';
  const used = new Array(n).fill(false);
  for (const idx of removeQueries) {
    if (!Number.isInteger(idx) || idx < 0 || idx >= n) return 'Each query is an index of nums.';
    if (used[idx]) return 'Each index may be removed only once.';
    used[idx] = true;
  }
  return null;
}

