function maximumSegmentSum(nums, removeQueries) {
  const n = nums.length;
  const parent = new Array(n).fill(-1);
  const segmentSum = new Array(n).fill(0);
  const answer = new Array(n).fill(0);
  let best = 0;

  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };

  const union = (a, b) => {
    const rootA = find(a);
    const rootB = find(b);
    parent[rootB] = rootA;
    segmentSum[rootA] += segmentSum[rootB];
  };

  for (let q = n - 1; q > 0; q--) {
    const index = removeQueries[q];
    parent[index] = index;
    segmentSum[index] = nums[index];
    if (index > 0 && parent[index - 1] !== -1) {
      union(index, index - 1);
    }
    if (index < n - 1 && parent[index + 1] !== -1) {
      union(index, index + 1);
    }
    best = Math.max(best, segmentSum[find(index)]);
    answer[q - 1] = best;
  }
  return answer;
}

