function maximumSegmentSum(nums, removeQueries) {
  const removed = new Array(nums.length).fill(false);
  const out = [];
  for (const idx of removeQueries) {
    removed[idx] = true;
    let top = 0;
    let run = 0;
    for (let i = 0; i < nums.length; i++) {
      run = removed[i] ? 0 : run + nums[i];
      if (run > top) top = run;
    }
    out.push(top);
  }
  return out;
}

