function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const cap = large || rand() < 0.2 ? 1000000000 : 10;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * cap));
  const removeQueries = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [removeQueries[i], removeQueries[j]] = [removeQueries[j], removeQueries[i]];
  }
  return [nums, removeQueries];
}
